def main():
    rows=json.loads((HERE/'sample_selection.json').read_text());lookup={}
    for line in ANNOTATIONS.strip().splitlines():
        n,kind,codes,note=line.split('|',3);lookup[int(n)]=(kind,codes.split(';'),note)
    assert len(rows)==len(lookup)==100
    for row in rows:
        kind,codes,note=lookup[row['sample_id']]
        row.update({'qualitative_review':'assistant_close_reading_original_comment','manual_evidence_type':kind,'manual_mechanism_codes':codes,'interpretation_and_limits':note,'age_verified':False,'premium_to_basic_verified':False,'incentive_status':'not_established','video_caption_verified':False,'medical_claim_status':'unverified_self_report_or_not_applicable','source_archive_path':'research/2026-11-03/closure/raw/user_runs/dataset_tiktok-comments-scraper_2026-11-03_12-02-32-061.json.gz'})
    (HERE/'qualitative_evidence.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
    with (HERE/'qualitative_evidence.csv').open('w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader()
        for row in rows:w.writerow({k:json.dumps(v,ensure_ascii=False) if isinstance(v,list) else v for k,v in row.items()})
    stats={'reviewed_comments':len(rows),'selection_methods':dict(collections.Counter('random_two_per_video' if r['selection_method'].startswith('random') else 'purposive_candidate' for r in rows)),'manual_types':dict(collections.Counter(r['manual_evidence_type'] for r in rows)),'scope':dict(collections.Counter(r['case_scope'] for r in rows)),'offtopic_in_random_calibration':sum(r['manual_evidence_type']=='off_topic' and r['selection_method'].startswith('random') for r in rows),'random_calibration_n':sum(r['selection_method'].startswith('random') for r in rows),'note':'Assistant readings; purposive mechanism enrichment; no target prevalence, human validation, saturation or medical validation claimed.'}
    (HERE/'qualitative_review_stats.json').write_text(json.dumps(stats,ensure_ascii=False,indent=2)+'\n');print(json.dumps(stats,indent=2))

if __name__=='__main__':main()
